struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *dest = NULL;
    struct user_struct *user = NULL;
    int ret;

    if (!ctx || !callout_info || !dest_keyring)
        return ERR_PTR(-EINVAL);

    dest = keyring_search(ctx, dest_keyring, NULL);
    if (IS_ERR(dest))
        return ERR_CAST(dest);

    user = get_current_user();
    if (!user) {
        ret = -ENOMEM;
        goto error;
    }

    key = key_alloc(&key_type_user, callout_info, callout_len,
                    user, NULL, flags, 0);
    if (IS_ERR(key)) {
        ret = PTR_ERR(key);
        key = NULL;
        goto error;
    }

    ret = key_instantiate(key, aux, callout_len, NULL);
    if (ret < 0)
        goto error;

    ret = key_link(key, dest);
    if (ret < 0)
        goto error;

    return key;

error:
    if (key)
        key_put(key);
    if (dest && dest != dest_keyring)
        key_put(dest);
    if (user)
        free_uid(user);
    return ERR_PTR(ret);
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *dest = NULL;
    struct user_struct *user = NULL;
    int ret;

    if (!ctx || !callout_info || !dest_keyring)
        return ERR_PTR(-EINVAL);

    ret = keyring_search_validate_context(ctx);
    if (ret < 0)
        return ERR_PTR(ret);

    dest = key_get(dest_keyring);
    if (!dest) {
        key = ERR_PTR(-ENOMEM);
        goto out;
    }

    user = get_current_user();
    if (!user) {
        key = ERR_PTR(-ENOMEM);
        goto out_put_dest;
    }

    key = key_alloc(&key_type_user, callout_info, callout_len,
                    user, NULL, 0, flags, NULL);
    if (IS_ERR(key)) {
        key = ERR_CAST(key);
        goto out_put_user;
    }

    ret = key_instantiate_and_link(key, callout_info, callout_len, dest, aux);
    if (ret < 0) {
        key = ERR_PTR(ret);
        goto out_free_key;
    }

    key_put(dest);
    dest = NULL;
    return key;

out_free_key:
    key_revoke(key);
    key_put(key);
out_put_user:
    put_user(user);
out_put_dest:
    key_put(dest);
out:
    return key;
}

