    if (!ctx || !dest_keyring || !callout_info || callout_len == 0) {
        return ERR_PTR(-EINVAL);
    }

    dest_keyring_ref = key_get(dest_keyring);
    if (!dest_keyring_ref) {
        return ERR_PTR(-ENOMEM);
    }

    user = get_current_user();
    if (!user) {
        key_put(dest_keyring_ref);
        return ERR_PTR(-ENOMEM);
    }

    key = key_alloc(&key_type_user, callout_info, callout_len, user, 0, flags, NULL);
